package com.danawa.search.analysis.dict

import com.danawa.io.DataInput
import com.danawa.io.DataOutput
import com.danawa.io.InputStreamDataInput
import com.danawa.io.OutputStreamDataOutput
import com.danawa.util.CharVector
import java.io.BufferedInputStream
import java.io.BufferedOutputStream
import java.io.File
import java.io.FileInputStream
import java.io.InputStream
import java.io.IOException
import java.io.OutputStream
import java.util.Collections
import java.util.HashSet

open class SetDictionary : SourceDictionary<Any> {

    private var set: MutableSet<CharSequence>

    constructor() : this(false)

    constructor(ignoreCase: Boolean) : super(ignoreCase, null, 0, null, DictionaryType.SET) {
        set = HashSet()
    }

    constructor(
        set: HashSet<CharSequence>,
        ignoreCase: Boolean,
        label: String?,
        seq: Int,
        tokenType: String?,
        type: DictionaryType
    ) : super(ignoreCase, label, seq, tokenType, type) {
        this.set = set
    }

    constructor(
        file: File,
        ignoreCase: Boolean,
        label: String?,
        seq: Int,
        tokenType: String?,
        type: DictionaryType
    ) : super(ignoreCase, label, seq, tokenType, type) {
        if (!file.exists()) {
            set = HashSet()
            logger.error("사전파일이 존재하지 않습니다. file={}", file.absolutePath)
            return
        }
        var inputStream: InputStream? = null
        try {
            inputStream = FileInputStream(file)
            set = HashSet() // Initialize before readFrom
            readFrom(inputStream)
        } catch (e: IOException) {
            set = HashSet()
            logger.error("", e)
        } finally {
            try { inputStream?.close() } catch (ignore: Exception) { }
        }
    }

    constructor(
        inputStream: InputStream,
        ignoreCase: Boolean,
        label: String?,
        seq: Int,
        tokenType: String?,
        type: DictionaryType
    ) : super(ignoreCase, label, seq, tokenType, type) {
        set = HashSet()
        try {
            readFrom(inputStream)
        } catch (e: IOException) {
            logger.error("", e)
        }
    }

    override fun addEntry(keyword: CharSequence?, values: Array<Any?>?, columnList: List<Any>?) {
        if (keyword == null) return
        val cv = CharVector(keyword.toString().trim(), ignoreCase)
        if (cv.length > 0) {
            set.add(cv.removeWhitespaces())
        }
    }

    fun getUnmodifiableSet(): Set<CharSequence> = Collections.unmodifiableSet(set)

    fun set(): MutableSet<CharSequence> = set

    fun setSet(set: MutableSet<CharSequence>) {
        this.set = set
    }

    fun contains(key: CharSequence): Boolean = set.contains(key)

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        val bufferedOut = if (out is BufferedOutputStream) out else BufferedOutputStream(out)
        val output: DataOutput = OutputStreamDataOutput(bufferedOut)
        val valueIter = set.iterator()
        // write size of set
        output.writeInt(set.size)
        // write values
        while (valueIter.hasNext()) {
            val value = valueIter.next()
            output.writeString(value.toString())
        }
        try { bufferedOut.flush() } catch (ignore: Exception) { }
    }

    @Throws(IOException::class)
    override fun readFrom(input: InputStream) {
        val bufferedIn = if (input is BufferedInputStream) input else BufferedInputStream(input)
        val dataInput: DataInput = InputStreamDataInput(bufferedIn)
        set = HashSet()
        val size = dataInput.readInt()
        for (entryInx in 0 until size) {
            set.add(CharVector(dataInput.readString(), ignoreCase))
        }
    }

    override fun addSourceLineEntry(line: CharSequence) {
        addEntry(line, null, null)
    }

    override fun reload(obj: Any?) {
        if (obj != null && obj is SetDictionary) {
            this.set = obj.set()
        } else {
            throw IllegalArgumentException("Reload dictionary argument error. argument = $obj")
        }
    }

    companion object {
        private val logger = SourceDictionary.logger
    }
}

