   458→    private fun getHighResult(): ExtractedEntry? {
   459→        var highEntry: ExtractedEntry? = null
   460→        for (k in result.indices) {
   461→            var entry: ExtractedEntry? = result[k]
   462→            entry = finalCheck(entry!!) ?: continue
   463→            charVector.init(source, entry.offset(), entry.column())
   464→
   465→            if (highEntry == null) {
   466→                highEntry = entry
   467→            } else {
   468→                if (isBetterThan(entry, highEntry)) {
   469→                    highEntry = entry
   470→                }
   471→            }
   472→        }
   473→        return highEntry
   474→    }
   475→
   476→    fun getBestResult(): ExtractedEntry {
   477→        var bestEntry = getHighResult()
   478→        if (bestEntry == null) {
   479→            bestEntry = ExtractedEntry(length - 1, length, TagProb.UNK, offset)
   480→            return bestEntry
   481→        }
   482→        return bestEntry
   483→    }
   484→
   485→    fun getTabularSize(): Int = tabular.size
   486→
   487→    /**
   488→     * 두 PosTag간의 룰기반 접속문법검사
   489→     */
   490→    protected fun isConnectableByRule(headTagProb: TagProb, headRow: Int, headColumn: Int, tail: ExtractedEntry): Boolean {
   491→        if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
   492→            return false
   493→        }
   494→        if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
   495→            return false
   496→        }
   497→        if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
   498→            return false
   499→        }
   500→        if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
   501→            if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
   502→                val ch = source[offset + tail.row() - tail.column() + 1]
   503→                if (ch == '은' || ch == '이' || ch == '을' || ch == '과') {
   504→                    if (!MorphUtil.hasLastElement(source[offset + headRow])) {
   505→                        return false
   506→                    }
   507→                } else if (ch == '는' || ch == '가' || ch == '를' || ch == '와') {
   508→                    if (MorphUtil.hasLastElement(source[offset + headRow])) {
   509→                        return false
   510→                    }
   511→                }
   512→            }
   513→        }
   514→
   515→        if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
   516→            if (tabular[tail.row()][tail.column() + headColumn] != null) {
   517→                return false
   518→            }
   519→        }
   520→        return true
   521→    }
   522→
   523→    /**
   524→     * 두 엔트리를 접속시 합치거나 이어붙이는 로직을 구현한다.
   525→     */
   526→    protected fun modifyAndConnect(tagProb: TagProb, row: Int, column: Int, tail: ExtractedEntry): ExtractedEntry {
   527→        val newEntry = ExtractedEntry(row, column, tagProb, offset)
   528→        return newEntry.next(tail)
   529→    }
   530→
   531→    private fun finalCheck(headEntry: ExtractedEntry): ExtractedEntry? {
   532→        if (headEntry.posTag() == PosTag.J) {
   533→            return null
   534→        }
   535→
   536→        var count = 0
   537→        if (headEntry.entryCount() >= 2) {
   538→            var current: ExtractedEntry? = headEntry
   539→            while (current != null) {
   540→                if (current.column() > 1) {
   541→                    break
   542→                } else {
   543→                    count++
   544→                }
   545→                current = current.next()
   546→            }
   547→        }
   548→
   549→        if (count == headEntry.entryCount()) {
   550→            if (headEntry.last().posTag() == PosTag.J) {
   551→                return headEntry
   552→            }
   553→            return null
   554→        }
   555→        return headEntry
   556→    }
   557→
   558→    /**
   559→     * Best 결과를 뽑을때 사용하는 비교로직.
   560→     */
   561→    protected fun isBetterThan(entry: ExtractedEntry, bestEntry: ExtractedEntry): Boolean {
   562→        if (entry.totalScore() > bestEntry.totalScore()) {
   563→            return true
   564→        }
   565→        return false
   566→    }
