   571→    class ExtractedEntry : Cloneable {
   572→        private var row: Int
   573→        private var column: Int
   574→        private var tagProb: TagProb
   575→        private var next: ExtractedEntry? = null
   576→        private var score: Double = 0.0
   577→        private var extracted: Boolean = false
   578→        private var _offset: Int
   579→
   580→        constructor(row: Int, column: Int, tagProb: TagProb) : this(row, column, tagProb, 0.0)
   581→
   582→        constructor(row: Int, column: Int, tagProb: TagProb, scoreAdd: Double) {
   583→            this.row = row
