   585→            this.tagProb = tagProb
   586→            this._offset = 0
   587→            this.score += (tagProb.prob() + scoreAdd)
   588→        }
   589→
   590→        constructor(row: Int, column: Int, tagProb: TagProb, offset: Int) {
   591→            this.row = row
