   593→            this.tagProb = tagProb
   594→            this._offset = offset
   595→            this.score += tagProb.prob()
   596→        }
   597→
   598→        fun tagProb(): TagProb = tagProb
   599→
   600→        fun posTag(): PosTag = tagProb.posTag()
   601→
   602→        fun tagProb(tagProb: TagProb) {
   603→            this.score -= this.tagProb.prob()
   604→            this.tagProb = tagProb
   605→            this.score += tagProb.prob()
   606→        }
   607→
   608→        fun offset(): Int = _offset + row - column + 1
   609→
   610→        fun row(): Int = row
   611→
   612→        fun row(row: Int) {
