package com.danawa.search.analysis.korean

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
import com.danawa.search.analysis.product.AnalyzeExceedException
import com.danawa.search.analysis.product.TokenTypes
import com.danawa.util.CharVector

import org.elasticsearch.common.logging.Loggers
import java.util.PriorityQueue

/**
 * Korean word extractor using CYK-style dynamic programming.
 * Extracts morphemes from Korean text using a probability-based scoring system.
 */
class KoreanWordExtractor @JvmOverloads constructor(
    private var koreanDict: ProductNameDictionary?,
    tabularSize: Int = 20
) {
    private val tabular: Array<Array<PosTagProbEntry?>>
    private val status: IntArray
    private val josaSet: MutableSet<CharVector>

    // 최상의 후보가 만들어지면 바로 리턴. 기본 true
    var fastResultOption: Boolean = true
    // 발견되었는지 여부
    private var fastResultFound: Boolean = false
    private var remnantOffset: Int = 0
    private var remnantLength: Int = 0
    private var isUnicode: Boolean = false
    private val charVector = CharVector()
    private val tabularStringer: TabularStringer
    private val entryStringer: EntryStringer

    private val queue = PriorityQueue<ExtractedEntry>(8) { o1, o2 ->
        (o2.totalScore() - o1.totalScore()).toInt()
    }

    private val result: MutableList<ExtractedEntry> = mutableListOf()

    protected var source: CharArray = CharArray(0)
    protected var offset: Int = 0
    protected var length: Int = 0

    init {
        tabular = Array(tabularSize) { row ->
            arrayOfNulls(row + 2)
        }
        status = IntArray(tabularSize)
        josaSet = mutableSetOf()
        val josaList = "은 는 이 가 을 를 에 과 와 의 로 만 께 에게 에서 으로 부터 라서 라고 께서 한테 처럼 같이 라는 하며 하고 까지 이라고 이라는 이라도 이라면 에서도 이기도"
        for (j in josaList.split("\\s".toRegex())) {
            josaSet.add(CharVector(j))
        }
        tabularStringer = TabularStringer()
        entryStringer = EntryStringer()
    }

    fun dictionary(): ProductNameDictionary? = koreanDict

    fun setKoreanDic(koreanDict: ProductNameDictionary?) {
        this.koreanDict = koreanDict
    }

    // Property setter is generated automatically by Kotlin for 'var fastResultOption'

    /**
     * 음절을 조합하여 사전에서 찾아준다. 찾은 단어와 tag는 table에 저장한다.
     */
    private fun doSegment(): ExtractedEntry? {
        val cv = CharVector(source, offset, length)
        // 길이가 1~2 단어는 완전매칭이 아니면 UNK이다.
        if (length == 1) {
            val tag = koreanDict?.find(cv)
            if (tag != null) {
                return ExtractedEntry(length - 1, length, tag[0], offset)
            }
            return when {
                isDigit(cv) -> ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
                isSymbol(cv) -> ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
                else -> ExtractedEntry(length - 1, length, TagProb.UNK, offset)
            }
        }
        val tag = koreanDict?.find(cv)
        if (tag != null) {
            return ExtractedEntry(length - 1, length, tag[0], offset)
        }
        val start = length - 1
        for (row in start downTo 0) {
            for (column in (row + 1) downTo 1) {
                cv.init(offset + row - column + 1, column)
                var isAlpha = false
                when {
                    isDigit(cv) -> {
                        tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
                        status[row]++
                    }
                    isSymbol(cv) -> {
                        tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
                        status[row]++
                    }
                    else -> {
                        if (isAlpha(cv)) {
                            if (column == 1) {
                                tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
                                continue
                            }
                            isAlpha = true
                        }
                        val tagList = koreanDict?.find(cv)
                        if (tagList != null) {
                            if (column == length) {
                                return ExtractedEntry(row, column, tagList[0], offset)
                            }
                            var chainedEntry: PosTagProbEntry? = null
                            for (i in tagList.indices) {
                                val tagProb = tagList[i]
                                if (i == 0) {
                                    chainedEntry = PosTagProbEntry(tagProb)
                                    tabular[row][column] = chainedEntry
                                } else {
                                    chainedEntry = chainedEntry?.next(tagProb)
                                }
                            }
                            status[row]++
                        } else {
                            tabular[row][column] = if (isAlpha) PosTagProbEntry(TagProb.ALPHA) else null
                        }

                        if (column < 3) {
                            if (josaSet.contains(cv)) {
                                val entry = PosTagProbEntry(TagProb.JOSA)
                                if (tabular[row][column] == null) {
                                    tabular[row][column] = entry
                                } else {
                                    entry.next = tabular[row][column]
                                    tabular[row][column] = entry
                                }
                                status[row]++
                            }
                        }
                    }
                }
            }
        }
        return null
    }

    private fun isUnicode(buffer: CharArray, offset: Int, length: Int): Boolean {
        for (inx in 0 until length) {
            val ch = buffer[offset + inx]
            if (ch.code > 127) {
                return true
            }
        }
        return false
    }

    private fun isDigit(cv: CharVector): Boolean {
        for (i in 0 until cv.length) {
            val ch = cv[i]
            if (ch !in '0'..'9') {
                return false
            }
        }
        return true
    }

    private fun isAlpha(cv: CharVector): Boolean {
        for (i in 0 until cv.length) {
            val ch = cv[i]
            if (!((ch in 'a'..'z') || (ch in 'A'..'Z'))) {
                return false
            }
        }
        return true
    }

    private fun isSymbol(cv: CharVector): Boolean {
        for (i in 0 until cv.length) {
            val chInt = cv[i].code
            if (Character.isLetterOrDigit(chInt)) {
                return false
            }
        }
        return true
    }

    private fun makeResult() {
        var headRow = -1
        for (row in (length - 1) downTo 0) {
            if (status[row] > 0) {
                headRow = row
                break
            }
        }

        try {
            if (headRow == -1) {
                addResult(ExtractedEntry(length - 1, length, TagProb.UNK, offset))
                return
            }
            if (headRow < length - 1) {
                val tail = ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset)
                connectAllTo(headRow, tail)
            } else {
                connectAllTo(headRow, null)
            }
            var tail: ExtractedEntry?
            while (queue.poll().also { tail = it } != null) {
                val connectRow = tail!!.row() - tail!!.column()
                if (status[connectRow] > 0) {
                    connectAllTo(connectRow, tail)
                } else {
                    connectTo(null, connectRow, -1, tail)
                }
            }
        } catch (e: AnalyzeExceedException) {
            logger.debug("Analyze exceed : " + e.message)
        }
    }

    @Throws(AnalyzeExceedException::class)
    private fun connectAllTo(headRow: Int, tail: ExtractedEntry?): Int {
        val rowData = tabular[headRow]
        var found = 0
        for (headColumn in (headRow + 1) downTo 1) {
            if (rowData[headColumn] != null) {
                val tagEntry = rowData[headColumn]!!
                entryStringer.set(tagEntry, source, headRow, headColumn, offset)
                if (tagEntry.tagProb?.posTag() != PosTag.ALPHA) {
                    connectTo(tagEntry, headRow, headColumn, tail)
                    found++
                }
            }
            if (found >= status[headRow]) {
                break
            }
        }
        if (!isUnicode) {
            val iter = result.iterator()
            while (iter.hasNext()) {
                val entry = iter.next()
                if (entry.last().posTag() == PosTag.UNK) {
                    iter.remove()
                }
            }
        }
        return found
    }

    @Throws(AnalyzeExceedException::class)
    private fun connectTo(
        headTagEntry: PosTagProbEntry?,
        headRow: Int,
        headColumn: Int,
        tail: ExtractedEntry?
    ): Int {
        var currentEntry = headTagEntry
        if (tail == null) {
            var found = 0
            while (currentEntry != null) {
                val headEntry = ExtractedEntry(headRow, headColumn, currentEntry.get()!!, offset)
                if (headEntry.row() - headEntry.column() < 0) {
                    addResult(headEntry)
                } else {
                    addQueue(headEntry)
                }
                currentEntry = currentEntry.next
                found++
            }
            return found
        }

        if (currentEntry == null) {
            for (column in 1..(headRow + 1)) {
                val row2 = headRow - column
                if (row2 < 0 || status[row2] > 0) {
                    // 2014-1-27처리..
                }
            }
            return 1
        }

        var found = 0
        while (currentEntry != null) {
            if (isConnectableByRule(currentEntry.get()!!, headRow, headColumn, tail)) {
                val newTail = modifyAndConnect(currentEntry.get()!!, headRow, headColumn, tail)
                if (newTail != null) {
                    if (newTail.row() - newTail.column() < 0) {
                        addResult(newTail)
                    } else {
                        addQueue(newTail)
                    }
                    found++
                }
            }
            currentEntry = currentEntry.next
        }
        return found
    }

    @Throws(AnalyzeExceedException::class)
    protected fun addQueue(entry: ExtractedEntry) {
        if (fastResultFound) {
            return
        }
        queue.add(entry)
        if (queue.size >= QUEUE_MAX) {
            throw AnalyzeExceedException("Queue size exceed ${queue.size} : ${String(source)}")
        }
    }

    @Throws(AnalyzeExceedException::class)
    protected fun addResult(entry: ExtractedEntry) {
        val e = finalCheck(entry) ?: return
        result.add(entry)

        if (fastResultOption && length > 6) {
            fastResultFound = true
            queue.clear()
        }

        if (result.size >= RESULT_MAX) {
            val tmpResult = getHighResult()
            result.clear()
            if (tmpResult != null) {
                result.add(tmpResult)
            }
        }
    }

    fun setInput(buffer: CharArray, length: Int): Int {
        return setInput(buffer, 0, length)
    }

    fun setInput(buffer: CharArray, offset: Int, length: Int): Int {
        var len = length
        remnantOffset = 0
        remnantLength = 0
        isUnicode = isUnicode(buffer, offset, len)
        status.fill(0)
        for (row in tabular.indices) {
