            for (inx in (offset + len) downTo (offset + 1)) {
                pptype = ptype
                ptype = type
                type = TokenTypes.getType(buffer[inx - 1].code)
                if (logger.isTraceEnabled) {
                    logger.trace(
                        "PP:{}/P:{}/T:{}/C:{} {} [{}/{}/{} | {}/{}/{}]", pptype, ptype, type, buffer[inx - 1],
                        inx - offset,
                        (pptype != null && (pptype != TokenTypes.ALPHA && pptype != TokenTypes.NUMBER)),
                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
                        (type != null), (pptype != null),
                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
                        (type != null && (type != TokenTypes.ALPHA && type != TokenTypes.NUMBER))
                    )
                }
