    @Throws(Exception::class)
    private fun testRule(testFile: String, isForQuery: Boolean) {
        var stream: java.io.InputStream? = null
        var reader: BufferedReader? = null
        var analyzer: ProductNameAnalyzer? = null
        val ptnAttr = Pattern.compile("<([A-Z_]+)([:]([0-9]+)[~]([0-9]+)){0,1}>")
        try {
            val dictionary = TestUtil.loadInternalDictionary()!!
            TestUtil.loadExtraDictionary(dictionary)

            stream = javaClass.getResourceAsStream(testFile)
            reader = BufferedReader(InputStreamReader(stream, "utf-8"))
            var rline: String?
            while (reader.readLine().also { rline = it } != null) {
                if (rline == "" || rline!!.startsWith("#")) {
                    continue
                }
                val testdata = rline!!.split("\t".toRegex()).toTypedArray()
                val input: Reader = StringReader(testdata[0])
                val option = AnalyzerOption(isForQuery, true, true, false, false)
                analyzer = ProductNameAnalyzer(dictionary, option)
                val tokenStream: TokenStream = analyzer.tokenStream("", input)
                val typeAttribute = tokenStream.addAttribute(TypeAttribute::class.java)
                val termAttribute = tokenStream.addAttribute(CharTermAttribute::class.java)
                val synonymAttribute = tokenStream.addAttribute(SynonymAttribute::class.java)
                val additionalTermAttribute = tokenStream.addAttribute(ExtraTermAttribute::class.java)
                val offsetAttribute = tokenStream.addAttribute(OffsetAttribute::class.java)

                logger.debug("--------------------------------------------------------------------------------")
                logger.debug("test for {}{}", "", testdata)
                logger.debug("--------------------------------------------------------------------------------")

                var inx = 0
                tokenStream.reset()

                while (tokenStream.incrementToken()) {
                    logger.debug(">> {}", termAttribute)
                    localAssertTrue(inx + 1 < testdata.size)
                    if (inx + 1 >= testdata.size) {
                        logger.debug("NOT FOUND!")
                        inx++
                        continue
                    }
                    val data = testdata[inx + 1].split(" ".toRegex()).toTypedArray()
                    localAssertTrue(data.size > 1)
                    var offset = intArrayOf(-1, -1)
                    run {
                        val mat = ptnAttr.matcher(data[1])
                        if (mat != null && mat.find()) {
                            logger.trace("GCOUNT:{} / {} / {} / {}", mat.groupCount(), mat.group(0), mat.group(1), mat.group(2))
                            if (mat.group(2) != null) {
                                offset = intArrayOf(
                                    Integer.parseInt(mat.group(3)),
                                    Integer.parseInt(mat.group(4))
                                )
                            }
                            data[1] = "<" + mat.group(1) + ">"
                        }
                    }

                    logger.debug("term:{}:{} / type:{}:{}", termAttribute, data[0], typeAttribute.type(), data[1])

                    localAssertTrue(termAttribute.toString() == data[0])
                    localAssertTrue(typeAttribute.type().toString() == data[1])
                    if (!(offset[0] == offset[1] && offset[1] == -1)) {
                        localAssertTrue(offsetAttribute.startOffset() == offset[0])
                        localAssertTrue(offsetAttribute.endOffset() == offset[1])
                    }
                    var inx2 = 0

                    if (synonymAttribute?.getSynonyms() != null) {
                        val synonymObj = synonymAttribute.getSynonyms()!!
                        var inx3 = 0
                        while (inx3 < synonymObj.size) {
                            val obj = synonymObj[inx3]
                            if (obj is CharVector) {
                                logger.debug(" |_synonym : {} / {}", obj, data)
                                localAssertTrue(obj.toString() == data[2 + inx2])
                            } else if (obj is List<*>) {
                                var extracted = ""
                                @Suppress("UNCHECKED_CAST")
                                val synonyms = obj as List<CharVector>
                                for (cv in synonyms) {
                                    extracted += "$cv "
                                }
                                logger.debug(" |_synonym : {}", obj)
                                logger.trace("EXTRACTED:{}", extracted)
                                localAssertTrue(obj.toString() == data[2 + inx2])
                            }
                            inx2++
                            inx3++
                        }
                    }

                    if (additionalTermAttribute != null) {
                        val termIter: Iterator<String> = additionalTermAttribute.iterator()
                        while (termIter.hasNext()) {
                            val term = termIter.next()
                            val type = typeAttribute.type()

                            try {
                                // logger.debug("additional term:{}", term)
                                localAssertTrue(inx + 1 < testdata.size)
                                try {
                                    logger.debug(
                                        "a-term:{}:{} / type:{}:{}",
                                        term,
                                        if (data.size > 2 + inx2) data[2 + inx2] else null,
                                        type,
                                        if (data.size > 3 + inx) data[3 + inx2] else null
                                    )
                                } catch (e: Exception) {
                                    logger.error("", e)
                                }
                                localAssertTrue(term == data[2 + inx2])
                                localAssertTrue(type == data[3 + inx2])
                            } catch (ex: Exception) {
                                logger.error("exception occurs for term \"{}\" / {}", term, type)
                                logger.error("", ex)
                                throw Exception(ex)
                            }
                            inx2 += 2
