private fun doSegment(): ExtractedEntry? {
    val cv = CharVector(source, offset, length)
    // 길이가 1~2 단어는 완전매칭이 아니면 UNK이다.
    if (length == 1) {
        val tag = koreanDict?.find(cv)
        if (tag != null) {
            return ExtractedEntry(length - 1, length, tag[0], offset)
        }
        return when {
            isDigit(cv) -> ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
            isSymbol(cv) -> ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
            else -> ExtractedEntry(length - 1, length, TagProb.UNK, offset)
        }
    }
    val tag = koreanDict?.find(cv)
    if (tag != null) {
        return ExtractedEntry(length - 1, length, tag[0], offset)
    }
    val start = length - 1
    for (row in start downTo 0) {
        for (column in (row + 1) downTo 1) {
            cv.init(offset + row - column + 1, column)
            var isAlpha = false
            when {
                isDigit(cv) -> {
                    tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
                    status[row]++
                }
                isSymbol(cv) -> {
                    tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
                    status[row]++
                }
                else -> {
                    if (isAlpha(cv)) {
                        if (column == 1) {
                            tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
                            continue
                        }
                        isAlpha = true
                    }
                    val tagList = koreanDict?.find(cv)
                    if (tagList != null) {
                        if (column == length) {
                            return ExtractedEntry(row, column, tagList[0], offset)
                        }
                        var chainedEntry: PosTagProbEntry? = null
                        for (i in tagList.indices) {
                            val tagProb = tagList[i]
                            if (i == 0) {
                                chainedEntry = PosTagProbEntry(tagProb)
                                tabular[row][column] = chainedEntry
                            } else {
                                chainedEntry = chainedEntry?.next(tagProb)
                            }
                        }
                        status[row]++
                    } else {
                        tabular[row][column] = if (isAlpha) PosTagProbEntry(TagProb.ALPHA) else null
                    }

                    if (column < 3) {
                        if (josaSet.contains(cv)) {
                            val entry = PosTagProbEntry(TagProb.JOSA)
                            if (tabular[row][column] == null) {
                                tabular[row][column] = entry
                            } else {
                                entry.next = tabular[row][column]
                                tabular[row][column] = entry
                            }
                            status[row]++
                        }
                    }
                }
            }
        }
    }
    return null
}

