### 2. `hashCode()` 수정: ignoreCase 상태 반영

**옵션 A: ignoreCase=false일 때 원본 문자로 해시 계산**
```kotlin
override fun hashCode(): Int {
    if (hash != 0) return hash  // 0도 캐싱
    var h = 1  // 0이 아닌 초기값 사용
    var off = _offset
    for (i in 0 until length) {
        var ch: Int = array[off++].code
        if (ignoreCase && ch in 'a'.code..'z'.code) {
            ch -= 32  // 대문자로 변환
        }
        h = 31 * h + ch
    }
    hash = h
    return h
}
```

**옵션 B: 항상 대문자 해시 유지 + equals도 항상 대문자 비교**
```kotlin
override fun equals(other: Any?): Boolean {
    if (this === other) return true
    if (other is CharVector) {
        if (_length != other._length) return false
        // 항상 대소문자 무시 비교 (hashCode와 일관성 유지)
        for (i in 0 until _length) {
            if (toUpperChar(array[_offset + i].code) != toUpperChar(other.array[other._offset + i].code)) {
                return false
            }
        }
        return true
    }
    return false
}
```

